public sealed class QualityAdministration(CoreDbContext db,ITransactionExecutor tx,ICompanyContext company,Application.Abstractions.Actors.ICurrentActor current,IAuditWriter audit,TimeProvider time):IQualityAdministration
{
 private Guid Company=>company.RequireCompanyId();private Guid Actor=>Guid.TryParse(current.Actor.UserId,out Guid id)?id:throw new InvalidOperationException("Actor required");private DateTimeOffset Now=>time.GetUtcNow();
 public Task<Result<QualityTemplateView>>CreateTemplateAsync(CreateQCTemplateCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{Result<QCChecklistTemplate>made=QCChecklistTemplate.Create(Company,c.Code,c.Name,c.ApplicableJobType,c.ProductTypeCode,Now);if(made.IsFailure||c.Criteria.Count==0)return Result.Failure<QualityTemplateView>(made.IsFailure?made.Error:QualityErrors.Invalid);if(await db.QCTemplates.AnyAsync(x=>x.Code==made.Value.Code,t))return Result.Failure<QualityTemplateView>(QualityErrors.Invalid);List<QCChecklistCriterion>criteria=[];foreach(CreateCriterionCommand x in c.Criteria){Result<QCChecklistCriterion>r=QCChecklistCriterion.Create(Company,made.Value.Id,x.Code,x.Name,x.CriterionType,x.IsRequired,x.SortOrder,x.MinimumValue,x.MaximumValue,x.AllowedChoiceCodes);if(r.IsFailure||criteria.Any(y=>y.Code==r.Value.Code))return Result.Failure<QualityTemplateView>(QualityErrors.Invalid);criteria.Add(r.Value);}db.Add(made.Value);db.AddRange(criteria);History("Template",made.Value.Id,"Created");Log("qc.template.created",made.Value.Id);return Result.Success(View(made.Value,criteria));},ct);
 public Task<Result<QualityTemplateView>>SetTemplateActiveAsync(Guid id,SetQualityActiveCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{QCChecklistTemplate?x=await db.QCTemplates.SingleOrDefaultAsync(v=>v.Id==id,t);if(x is null)return Result.Failure<QualityTemplateView>(QualityErrors.NotFound);Result r=x.SetActive(c.IsActive,c.Version,Now);if(r.IsFailure)return Result.Failure<QualityTemplateView>(r.Error);History("Template",id,c.IsActive?"Activated":"Deactivated");Log("qc.template.updated",id);return Result.Success(View(x,await db.QCTemplateCriteria.Where(v=>v.TemplateId==id).ToListAsync(t)));},ct);
 public Task<Result<DefectTypeView>>CreateDefectTypeAsync(CreateDefectTypeCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{Result<DefectType>r=DefectType.Create(Company,c.Code,c.Name,c.CategoryCode,c.Severity,c.IsBlocking,Now);if(r.IsFailure||await db.DefectTypes.AnyAsync(x=>x.Code==r.Value.Code,t))return Result.Failure<DefectTypeView>(r.IsFailure?r.Error:QualityErrors.Invalid);db.Add(r.Value);History("DefectType",r.Value.Id,"Created");Log("qc.defect_type.created",r.Value.Id);return Result.Success(View(r.Value));},ct);
 public Task<Result<DefectTypeView>>SetDefectTypeActiveAsync(Guid id,SetQualityActiveCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{DefectType?x=await db.DefectTypes.SingleOrDefaultAsync(v=>v.Id==id,t);if(x is null)return Result.Failure<DefectTypeView>(QualityErrors.NotFound);Result r=x.SetActive(c.IsActive,c.Version,Now);if(r.IsFailure)return Result.Failure<DefectTypeView>(r.Error);History("DefectType",id,c.IsActive?"Activated":"Deactivated");Log("qc.defect_type.updated",id);return Result.Success(View(x));},ct);
 public Task<Result<InspectionView>>StartInspectionAsync(CreateInspectionCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{ProductionJob?j=await db.ProductionJobs.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==c.ProductionJobId,t);QCChecklistTemplate?template=await db.QCTemplates.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==c.TemplateId&&x.IsActive,t);if(j is null||template is null||j.Status is not(ProductionJobStatus.Completed or ProductionJobStatus.Failed)||template.ApplicableJobType is not null&&template.ApplicableJobType!=j.JobType)return Result.Failure<InspectionView>(QualityErrors.Invalid);QCInspection?existing=await db.QCInspections.SingleOrDefaultAsync(x=>x.ProductionJobId==j.Id,t);if(existing is not null)return Result.Success(View(existing));if(c.ParentInspectionId is not null&&!await db.QCInspections.AnyAsync(x=>x.Id==c.ParentInspectionId&&x.Status==QCInspectionStatus.Rejected,t))return Result.Failure<InspectionView>(QualityErrors.Invalid);QCInspection x=QCInspection.Create(Company,j.OrderId,j.OrderItemId,j.Id,template.Id,template.Version,Actor,c.ParentInspectionId,j.ReproductionRequestId,Now);db.Add(x);History("Inspection",x.Id,"Started");Log("qc.inspection.started",x.Id);return Result.Success(View(x));},ct);
 public Task<Result<InspectionView>>GetInspectionAsync(Guid id,CancellationToken ct)=>tx.ExecuteAsync(async t=>{QCInspection?x=await db.QCInspections.AsNoTracking().SingleOrDefaultAsync(v=>v.Id==id,t);return x is null?Result.Failure<InspectionView>(QualityErrors.NotFound):Result.Success(View(x));},ct);
 public Task<Result>RecordResultAsync(Guid id,RecordCriteriaResultCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{QCInspection?i=await db.QCInspections.SingleOrDefaultAsync(x=>x.Id==id,t);QCChecklistCriterion?criterion=await db.QCTemplateCriteria.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==c.CriterionId,t);if(i is null||criterion is null||criterion.TemplateId!=i.TemplateId||i.Status is not(QCInspectionStatus.InProgress or QCInspectionStatus.ManagementReview)||await db.QCCriteriaResults.AnyAsync(x=>x.InspectionId==id&&x.TemplateCriterionId==c.CriterionId,t))return Result.Failure(QualityErrors.Invalid);Result<QCCriteriaResult>r=QCCriteriaResult.Create(Company,id,criterion,c.PassFailValue,c.NumericValue,c.TextValue,c.ChoiceCode,Actor,Now);if(r.IsFailure)return Result.Failure(r.Error);db.Add(r.Value);History("Inspection",id,"CriterionRecorded",criterion.Code);Log("qc.result.recorded",id);return Result.Success();},ct);
 public Task<Result>RecordDefectAsync(Guid id,RecordDefectCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{QCInspection?i=await db.QCInspections.SingleOrDefaultAsync(x=>x.Id==id,t);DefectType?d=await db.DefectTypes.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==c.DefectTypeId&&x.IsActive,t);if(i is null||d is null||i.Status is not(QCInspectionStatus.InProgress or QCInspectionStatus.ManagementReview))return Result.Failure(QualityErrors.Invalid);if(c.CriteriaResultId is not null&&!await db.QCCriteriaResults.AnyAsync(x=>x.Id==c.CriteriaResultId&&x.InspectionId==id,t)||c.EvidenceFileVersionId is not null&&!await db.FileVersions.AnyAsync(x=>x.Id==c.EvidenceFileVersionId,t))return Result.Failure(QualityErrors.Invalid);Result<QCDefect>r=QCDefect.Create(Company,id,c.CriteriaResultId,d.Id,c.Quantity,c.Severity,c.Notes,c.EvidenceFileVersionId,Actor,Now);if(r.IsFailure)return Result.Failure(r.Error);db.Add(r.Value);History("Inspection",id,"DefectRecorded",d.Code);Log("qc.defect.recorded",id);return Result.Success();},ct);
 public Task<Result<InspectionView>>ApproveAsync(Guid id,long version,CancellationToken ct)=>tx.ExecuteAsync(async t=>{QCInspection?i=await db.QCInspections.SingleOrDefaultAsync(x=>x.Id==id,t);if(i is null)return Result.Failure<InspectionView>(QualityErrors.NotFound);int required=await db.QCTemplateCriteria.CountAsync(x=>x.TemplateId==i.TemplateId&&x.IsRequired,t),done=await db.QCCriteriaResults.CountAsync(x=>x.InspectionId==id&&x.IsRequired,t);if(done<required)return Result.Failure<InspectionView>(QualityErrors.CriteriaIncomplete);bool blocking=await(from d in db.QCDefects join k in db.DefectTypes on d.DefectTypeId equals k.Id where d.InspectionId==id&&k.IsBlocking select d.Id).AnyAsync(t);if(blocking)return Result.Failure<InspectionView>(QualityErrors.BlockingDefect);return Finish(i,i.Approve(version,Now),"Approved",null);},ct);
 public Task<Result<InspectionView>>SuspendAsync(Guid id,QualityReasonCommand c,CancellationToken ct)=>Change(id,c.Version,"Suspended",c.Reason,(x,n)=>x.Suspend(c.Reason,c.Version,n),ct);public Task<Result<InspectionView>>ReviewAsync(Guid id,QualityReasonCommand c,CancellationToken ct)=>Change(id,c.Version,"ManagementReview",c.Reason,(x,n)=>x.Review(c.Reason,c.Version,n),ct);public Task<Result<InspectionView>>RejectAsync(Guid id,QualityReasonCommand c,CancellationToken ct)=>Change(id,c.Version,"Rejected",c.Reason,(x,n)=>x.Reject(c.Reason,c.Version,n),ct);
 private Task<Result<InspectionView>>Change(Guid id,long v,string evt,string?summary,Func<QCInspection,DateTimeOffset,Result>f,CancellationToken ct)=>tx.ExecuteAsync(async t=>{QCInspection?i=await db.QCInspections.SingleOrDefaultAsync(x=>x.Id==id,t);return i is null?Result.Failure<InspectionView>(QualityErrors.NotFound):Finish(i,f(i,Now),evt,summary);},ct);private Result<InspectionView>Finish(QCInspection i,Result r,string evt,string?summary){if(r.IsFailure)return Result.Failure<InspectionView>(r.Error);History("Inspection",i.Id,evt,summary);Log($"qc.inspection.{evt.ToLowerInvariant()}",i.Id);return Result.Success(View(i));}
 public Task<Result<ReproductionView>>RequestReproductionAsync(Guid inspectionId,CreateReproductionCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{QCInspection?i=await db.QCInspections.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==inspectionId,t);if(i is null||i.Status!=QCInspectionStatus.Rejected)return Result.Failure<ReproductionView>(QualityErrors.ReproductionNotAllowed);ReproductionRequest?existing=await db.ReproductionRequests.SingleOrDefaultAsync(x=>x.SourceInspectionId==inspectionId,t);if(existing is not null)return Result.Success(View(existing));ProductionJob source=await db.ProductionJobs.AsNoTracking().SingleAsync(x=>x.Id==i.ProductionJobId,t);Guid root=source.RootProductionJobId??source.Id;int depth=source.ReproductionDepth+1;Result<ReproductionRequest>r=ReproductionRequest.Create(Company,i.Id,i.OrderId,i.OrderItemId,source.Id,root,c.RequestedStage,c.Quantity,c.Reason,Actor,depth,Now);if(r.IsFailure)return Result.Failure<ReproductionView>(r.Error);db.Add(r.Value);History("Reproduction",r.Value.Id,"Requested",c.Reason);Log("qc.reproduction.requested",r.Value.Id);return Result.Success(View(r.Value));},ct);
 public Task<Result<IReadOnlyList<Guid>>>CreateReproductionJobsAsync(Guid requestId,long version,CancellationToken ct)=>tx.ExecuteAsync(async t=>{ReproductionRequest?r=await db.ReproductionRequests.SingleOrDefaultAsync(x=>x.Id==requestId,t);if(r is null)return Result.Failure<IReadOnlyList<Guid>>(QualityErrors.NotFound);List<ProductionJob>existing=await db.ProductionJobs.Where(x=>x.ReproductionRequestId==requestId).ToListAsync(t);if(existing.Count>0)return Result.Success<IReadOnlyList<Guid>>(existing.Select(x=>x.Id).ToArray());ProductionJob source=await db.ProductionJobs.AsNoTracking().SingleAsync(x=>x.Id==r.SourceProductionJobId,t);List<(ProductionJobType,Guid?,Guid?,Guid?)>specs=[];if(r.RequestedStage is ReproductionStage.DesignPreparation or ReproductionStage.FullItem)specs.Add((ProductionJobType.DesignPreparation,null,null,null));if(r.RequestedStage is ReproductionStage.Print or ReproductionStage.FullItem){var ops=await db.OrderPrintOperations.AsNoTracking().Where(x=>x.OrderItemId==r.OrderItemId&&x.IsActive).ToListAsync(t);foreach(var op in ops)specs.Add((ProductionJobType.Print,op.Id,op.ArtworkVersionId,op.FileVersionId));if(r.RequestedStage==ReproductionStage.Print&&specs.Count==0)return Result.Failure<IReadOnlyList<Guid>>(QualityErrors.Invalid);}if(r.RequestedStage is ReproductionStage.HeatPress or ReproductionStage.FullItem)specs.Add((ProductionJobType.HeatPress,null,null,null));List<ProductionJob>jobs=[];foreach(var s in specs){Result<ProductionJob>made=ProductionJob.CreateReproduction(Company,r.OrderId,r.OrderItemId,s.Item2,s.Item1,r.Id,source.Id,r.RootProductionJobId,r.Depth,s.Item3,s.Item4,Now);if(made.IsFailure)return Result.Failure<IReadOnlyList<Guid>>(made.Error);jobs.Add(made.Value);db.Add(made.Value);db.ProductionJobHistory.Add(ProductionJobHistory.Create(Company,made.Value.Id,"Created",Actor,Now,$"Reproduction {r.Id}"));}Result marked=r.MarkJobsCreated(version,Now);if(marked.IsFailure)return Result.Failure<IReadOnlyList<Guid>>(marked.Error);History("Reproduction",r.Id,"JobsCreated",jobs.Count.ToString());Log("qc.reproduction.jobs_created",r.Id);return Result.Success<IReadOnlyList<Guid>>(jobs.Select(x=>x.Id).ToArray());},ct);
 public Task<Result<IReadOnlyList<QualityHistoryView>>>HistoryAsync(Guid id,CancellationToken ct)=>tx.ExecuteAsync(async t=>Result.Success<IReadOnlyList<QualityHistoryView>>((await db.QCHistory.AsNoTracking().Where(x=>x.EntityId==id).OrderBy(x=>x.OccurredAtUtc).ThenBy(x=>x.Id).ToListAsync(t)).Select(x=>new QualityHistoryView(x.Id,x.EntityType,x.EntityId,x.EventType,x.ActorUserId,x.OccurredAtUtc,x.Summary)).ToArray()),ct);
 public Task<Result<QualityAnalyticsView>>AnalyticsAsync(DateTimeOffset start,DateTimeOffset end,int top,CancellationToken ct)=>tx.ExecuteAsync(async t=>{if(end<=start||top is<1 or>50)return Result.Failure<QualityAnalyticsView>(QualityErrors.Invalid);var q=db.QCInspections.AsNoTracking().Where(x=>x.CreatedAtUtc>=start&&x.CreatedAtUtc<end);long total=await q.LongCountAsync(t),approved=await q.LongCountAsync(x=>x.Outcome==QCOutcome.Approved,t),rejected=await q.LongCountAsync(x=>x.Outcome==QCOutcome.Rejected,t),suspended=await q.LongCountAsync(x=>x.Status==QCInspectionStatus.Suspended,t),repros=await db.ReproductionRequests.LongCountAsync(x=>x.RequestedAtUtc>=start&&x.RequestedAtUtc<end,t);var defects=await(from d in db.QCDefects join k in db.DefectTypes on d.DefectTypeId equals k.Id where d.RecordedAtUtc >= start && d.RecordedAtUtc < end group d by new{k.Code,k.Name}into g orderby g.Count() descending select new DefectFrequencyView(g.Key.Code,g.Key.Name,g.LongCount(),g.Sum(x=>x.Quantity))).Take(top).ToListAsync(t);return Result.Success(new QualityAnalyticsView(total,approved,rejected,suspended,repros,defects));},ct);
 private void History(string entity,Guid id,string evt,string?summary=null)=>db.QCHistory.Add(QCHistory.Create(Company,entity,id,evt,Actor,Now,summary));private void Log(string action,Guid id)=>audit.Write(new(action,"quality",id.ToString(),ChangeKind:AuditChangeKind.Modified));
 private static QualityTemplateView View(QCChecklistTemplate x,IReadOnlyList<QCChecklistCriterion>c)=>new(x.Id,x.Code,x.Name,x.ApplicableJobType,x.ProductTypeCode,x.IsActive,x.Version,c.OrderBy(v=>v.SortOrder).Select(v=>new QualityCriterionView(v.Id,v.Code,v.Name,v.CriterionType,v.IsRequired,v.SortOrder,v.MinimumValue,v.MaximumValue,v.AllowedChoiceCodes)).ToArray());private static DefectTypeView View(DefectType x)=>new(x.Id,x.Code,x.Name,x.CategoryCode,x.Severity,x.IsBlocking,x.IsActive,x.Version);private static InspectionView View(QCInspection x)=>new(x.Id,x.OrderId,x.OrderItemId,x.ProductionJobId,x.TemplateId,x.TemplateVersion,x.InspectorUserId,x.Status,x.Outcome,x.ParentInspectionId,x.ReproductionRequestId,x.StartedAtUtc,x.CompletedAtUtc,x.DecisionReason,x.Version);private static ReproductionView View(ReproductionRequest x)=>new(x.Id,x.SourceInspectionId,x.OrderId,x.OrderItemId,x.SourceProductionJobId,x.RootProductionJobId,x.RequestedStage,x.Quantity,x.Reason,x.Status,x.Depth,x.Version);
}
